SELECT /* QueryID : com.demo.proworks.wbs.selectListWbs */ TASK_ID as taskId, TASK_NAME as taskName, TASK_DES as taskDes, TASK_STATUS as taskStatus, IS_TEST as isTest, TASK_DEPTH as taskDepth, STG_ID as stgId, PT_TASK_ID as ptTaskId, TASK_SEQ as taskSeq, TASK_ST as taskSt, TASK_ET as taskEt, TASK_RST as taskRst, TASK_RET as taskRet, TASK_ASI as taskAsi, TASK_RATE as taskRate, PJT_ID as pjtId FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT * FROM TASK WHERE PJT_ID = #{pjtId}
AND TASK_ID like '%${scTaskId}%'
AND TASK_NAME like '%${scTaskName}%'
AND TASK_STATUS like '%${scTaskStatus}%'
AND STG_ID like '%${scStgId}%'
AND TASK_ASI like '%${scTaskAsi}%'
AND TASK_RATE like '%${scTaskRate}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}
